function smartAlignLyrics(rawLines: { time: number; text: string }[]) {
  if (!Array.isArray(rawLines) || rawLines.length === 0) return [];
  const sorted = [...rawLines].sort((a, b) => a.time - b.time);
  const aligned: { time: number; text: string }[] = [];

  // If first vocal line starts after 3.0s, insert intro musical dots
  if (sorted[0].time > 3.0) {
    aligned.push({ time: 0, text: "•••" });
  }

  for (let i = 0; i < sorted.length; i++) {
    const cur = sorted[i];
    aligned.push(cur);

    const next = sorted[i + 1];
    if (next) {
      const wordCount = (cur.text || "").split(/\s+/).filter(Boolean).length;
      const vocalDuration = Math.min(6.5, Math.max(1.8, wordCount * 0.45 + 0.8));
      const gap = next.time - cur.time;

      // If gap to next line is longer than vocalDuration + 3.8s, insert instrumental interlude
      if (gap > vocalDuration + 3.8 && cur.text !== "•••" && next.text !== "•••") {
        const interludeStart = Number((cur.time + vocalDuration + 0.5).toFixed(2));
        if (interludeStart < next.time - 1.5) {
          aligned.push({ time: interludeStart, text: "•••" });
        }
      }
    }
  }

  return aligned;
}

// High-performance in-memory cache for 0ms response on repeat queries
const LYRICS_CACHE = new Map<string, { lyrics: any[]; synced: boolean }>();

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const rawArtist = (searchParams.get("artist") || "").trim();
  const rawTitle = (searchParams.get("title") || "").trim();

  if (!rawArtist && !rawTitle) {
    return NextResponse.json({ lyrics: [] });
  }

  const cacheKey = `${rawArtist.toLowerCase()}:::${rawTitle.toLowerCase()}`;
  if (LYRICS_CACHE.has(cacheKey)) {
    return NextResponse.json(LYRICS_CACHE.get(cacheKey));
  }

  // Unicode normalization (e.g. eńau -> enau)
  const normArtist = rawArtist.normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();
  const normTitle = rawTitle.normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();

  const cleanTitle = normTitle
    .toLowerCase()
    .replace(/\(.*?\)/g, "")
    .replace(/\[.*?\]/g, "")
    .replace(/(official\s*(music\s*)?video|audio|lyrics?|visualizer)/gi, "")
    .replace(/[-–].*$/, "")
    .replace(/[^\w\s]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();

  const primaryArtist = normArtist
    .split(/[,&/]|feat\.|ft\.|with/i)[0]
    .replace(/[^\w\s]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();

  // 1. Check curated exact-matched lyrics first (Instant 0ms, zero lag, perfect studio sync)
  for (const [key, lyricsList] of Object.entries(CURATED_LYRICS)) {
    const normKey = key.toLowerCase().replace(/[^\w\s]/gi, " ").replace(/\s+/g, " ").trim();
    if (cleanTitle === normKey || cleanTitle.includes(normKey) || normKey.includes(cleanTitle)) {
      const resData = { lyrics: lyricsList, synced: true };
      LYRICS_CACHE.set(cacheKey, resData);
      return NextResponse.json(resData);
    }
  }

  try {
    let data: any = null;

    // 2. Fetch direct get with primaryArtist and cleanTitle
    const directUrl = `https://lrclib.net/api/get?artist_name=${encodeURIComponent(primaryArtist)}&track_name=${encodeURIComponent(cleanTitle)}`;
    try {
      const res = await fetch(directUrl, {
        headers: { "User-Agent": "BrnsicMusicApp/1.0" }
      });
      if (res.ok) {
        data = await res.json();
      }
    } catch(e) {}

    // 3. Fallback search with artist + cleanTitle
    if (!data || !data.syncedLyrics) {
      try {
        const searchRes = await fetch(
          `https://lrclib.net/api/search?q=${encodeURIComponent(primaryArtist + " " + cleanTitle)}`,
          {
            headers: { "User-Agent": "BrnsicMusicApp/1.0" }
          }
        );
        if (searchRes.ok) {
          const results = await searchRes.json();
          if (Array.isArray(results) && results.length > 0) {
            data = results.find((r: any) => r.syncedLyrics) || results[0];
          }
        }
      } catch(e) {}
    }

    // 4. Fallback search with cleanTitle alone
    if (!data || !data.syncedLyrics) {
      try {
        const searchTitleRes = await fetch(
          `https://lrclib.net/api/search?q=${encodeURIComponent(cleanTitle)}`,
          {
            headers: { "User-Agent": "BrnsicMusicApp/1.0" }
          }
        );
        if (searchTitleRes.ok) {
          const results = await searchTitleRes.json();
          if (Array.isArray(results) && results.length > 0) {
            data = results.find((r: any) => r.syncedLyrics) || results[0];
          }
        }
      } catch(e) {}
    }

    if (data && data.syncedLyrics) {
      const lines = data.syncedLyrics.split("\n");
      const parsed: { time: number; text: string }[] = [];
      const timeReg = /\[(\d{2}):(\d{2})(?:\.(\d{2,3}))?\]/;

      lines.forEach((l: string) => {
        const m = timeReg.exec(l);
        if (m) {
          const min = parseInt(m[1], 10);
          const sec = parseInt(m[2], 10);
          const ms = m[3] ? parseInt(m[3].padEnd(3, "0"), 10) : 0;
          const text = l.replace(timeReg, "").trim();
          if (text) {
            parsed.push({ time: Number((min * 60 + sec + ms / 1000).toFixed(2)), text });
          }
        }
      });

      if (parsed.length > 0) {
        const smartLyrics = smartAlignLyrics(parsed);
        const resData = { lyrics: smartLyrics, synced: true };
        LYRICS_CACHE.set(cacheKey, resData);
        return NextResponse.json(resData);
      }
    }

    if (data && data.plainLyrics) {
      const lines = data.plainLyrics
        .split("\n")
        .map((l: string) => l.trim())
        .filter((l: string) => l.length > 0);
      const estStep = 4.2;
      const parsed = lines.map((text: string, i: number) => ({
        time: Number((i * estStep).toFixed(2)),
        text
      }));
      const smartLyrics = smartAlignLyrics(parsed);
      const resData = { lyrics: smartLyrics, synced: false };
      LYRICS_CACHE.set(cacheKey, resData);
      return NextResponse.json(resData);
    }

    const fallbackData = {
      lyrics: [
        { time: 0, text: rawTitle },
        { time: 4, text: rawArtist },
        { time: 8, text: "Lirik tersinkronisasi sedang disiapkan untuk lagu ini" }
      ],
      synced: false
    };
    LYRICS_CACHE.set(cacheKey, fallbackData);
    return NextResponse.json(fallbackData);
  } catch (err: any) {
    return NextResponse.json({
      lyrics: [
        { time: 0, text: rawTitle },
        { time: 4, text: rawArtist },
        { time: 8, text: "Menyiapkan lirik sinkron dan streaming audio..." }
      ],
      synced: false
    });
  }
}
